import{_ as n,o as i,c as e,a1 as t}from"./chunks/framework.DxqwKiYY.js";const s="/pelatihan-webgis-big/assets/image1.C695EMHW.png",g="/pelatihan-webgis-big/assets/image2.BZZEgnd5.png",p="/pelatihan-webgis-big/assets/image3.CBq4r66R.png",r="/pelatihan-webgis-big/assets/image4.DtEK_Ef9.png",m="/pelatihan-webgis-big/assets/image5.DsurKF0L.png",o="/pelatihan-webgis-big/assets/image6.DuxdohZ4.png",l="/pelatihan-webgis-big/assets/image7.CJ3dM9Ye.png",u="/pelatihan-webgis-big/assets/image8.BOWtCp3O.png",k="/pelatihan-webgis-big/assets/image9.wNQpa5uz.png",b="/pelatihan-webgis-big/assets/image10.Dz2cuDP8.png",d="/pelatihan-webgis-big/assets/image11.D49rjIbf.png",h="/pelatihan-webgis-big/assets/image12.4lFv6Z4b.png",c="/pelatihan-webgis-big/assets/image.BoKp9hT_.png",f="/pelatihan-webgis-big/assets/image14.CzPCtay3.png",_="/pelatihan-webgis-big/assets/image15.vYlpQz82.png",w="/pelatihan-webgis-big/assets/image16.Dy-WAhiV.png",y="/pelatihan-webgis-big/assets/image17.BwTVoAws.png",j="/pelatihan-webgis-big/assets/image18.DnC65eZD.png",P="/pelatihan-webgis-big/assets/image%201.EG1ijQSl.png",I="/pelatihan-webgis-big/assets/image%202.RJgo18Um.png",D="/pelatihan-webgis-big/assets/image%203.DacyLB-s.png",q=JSON.parse('{"title":"Interaksi Pengguna","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Interaksi Pengguna.md","filePath":"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Interaksi Pengguna.md"}'),B={name:"Training WebGIS BIG/Modul 3 - Pengembangan Frontend Peta Web 3D/Interaksi Pengguna.md"};function T(v,a,x,C,F,S){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="interaksi-pengguna" tabindex="-1">Interaksi Pengguna <a class="header-anchor" href="#interaksi-pengguna" aria-label="Permalink to &quot;Interaksi Pengguna&quot;">​</a></h1><p><strong>Screen space event handler (klik, hover), pemilahan objek 3D (3D Object Picking) dan kustomisasi InfoBox untuk data semantik)</strong></p><h2 id="membuat-fungsi-interaksi-pengguna" tabindex="-1"><strong>Membuat Fungsi Interaksi Pengguna</strong> <a class="header-anchor" href="#membuat-fungsi-interaksi-pengguna" aria-label="Permalink to &quot;**Membuat Fungsi Interaksi Pengguna**&quot;">​</a></h2><ol><li><p>Tahap satu buat file baru pada folder <strong>components</strong> dengan nama file yaitu <strong>addInteraksiPengguna.jsx</strong>.</p><p><img src="'+s+'" alt=""></p></li><li><p>Tahap kedua buat fungsi <strong>addInteraksiPengguna</strong> yang digunakan untuk menambahkan kemampuan interaksi pengguna pada peta 3D. Kemudian tambahkan parameter <strong>viewer</strong>.</p><p><img src="'+g+'" alt=""></p></li><li><p>Tahap ketiga buat variabel <strong>const cesium = windows.cesium</strong> untuk mengambil library Cesium yang sebelumnya telah tersedia di halaman Cesium Viewer.</p><p><img src="'+p+'" alt=""></p></li><li><p>Tahap keempat buat variabel <strong>infobox</strong> yang akan digunakan untuk menampilkan informasi ketika pengguna mengklik layer pada peta.</p><p><img src="'+r+'" alt=""></p></li><li><p>Selanjutnya buat elemen <strong>infoBox.style.cssText</strong> yang berfungsi untuk mengatur tampilan dan posisi kotak informasi <strong>(infoBox)</strong> pada halaman peta, meliputi posisi di bagian bawah kiri, warna latar putih, ukuran teks, jarak isi, bentuk sudut, bayangan, serta menyembunyikan kotak informasi pada saat awal sebelum pengguna memilih objek.</p><p><img src="'+m+'" alt=""></p></li><li><p>Kemudian buat <strong>viewer.container.appendChild(infoBox);</strong> yang digunakan untuk menambahkan kotak informasi kedalam tampilan peta.</p><p><img src="'+o+'" alt=""></p></li><li><p>Tahap kelima buat variabel <strong>handler</strong> atau pendeteksi interaksi pengguna pada area tampilan peta (canvas), sehingga sistem dapat merespons aktivitas seperti klik atau pergerakan mouse pada peta.</p><p><img src="'+l+'" alt=""></p></li><li><p>Tahap keenam buat fungsi untuk menambahkan aksi yang akan dijalankan ketika pengguna melakukan klik kiri <strong>(LEFT_CLICK)</strong> pada area peta 3D, sehingga sistem dapat merespons dan memproses objek yang dipilih.</p><p><img src="'+u+'" alt=""></p></li><li><p>Selanjutnya didalam fungsi tersebut buat variabel <strong>const objek</strong> untuk mendeteksi dan mengambil objek pada peta 3D berdasarkan posisi yang diklik.</p><p><img src="'+k+'" alt=""></p></li><li><p>Kemudian buat kondisi <strong>if</strong> untuk memeriksa apakah terdapat objek yang berhasil dipilih oleh pengguna, dan jika tidak ada objek pada lokasi yang diklik maka kotak informasi tidak ditampilkan.</p><p><img src="'+b+'" alt=""></p></li><li><p>Tahap berikutnya tambahkan fungsi untuk menyiapkan variabel <strong>namaProperti</strong> sebagai tempat menyimpan daftar atribut objek serta variabel <strong>judul</strong> untuk menentukan judul informasi.</p><p><img src="'+d+'" alt=""></p></li><li><p>Selanjutnya buat kondisi <strong>if</strong> untuk memeriksa apakah objek yang dipilih pengguna merupakan objek bertipe 3D Tiles, sehingga dapat menentukan cara yang sesuai untuk mengambil informasi.</p><p><img src="'+h+'" alt=""></p></li><li><p>Pada fungsi <strong>if</strong> diatas, tambahkan fungsi untuk mengambil seluruh atribut dan nama dari objek 3D Tiles yang dipilih, kemudian menyusun serta menampilkan informasi tersebut ke dalam kotak informasi (infoBox).</p><p><img src="'+c+'" alt="image.png"></p></li><li><p>Tahap berikutnya tambahkan fungsi <strong>else if</strong> untuk memeriksa apakah objek yang dipilih memiliki data atribut, kemudian mengambil nama serta seluruh informasi yang tersedia pada objek tersebut untuk ditampilkan ke dalam kotak informasi (infoBox).</p><p><img src="'+f+'" alt=""></p></li><li><p>Tahap terakhir buat fungsi <strong>else</strong> untuk menampilkan pesan bahwa objek tidak memiliki data apabila informasi objek tidak ditemukan, kemudian menampilkan kotak informasi (infoBox).</p><p><img src="'+_+'" alt=""></p></li><li><p>Berikut ini merupakan keseluruhan script untuk interaksi pengguna.</p><p><img src="'+w+'" alt=""></p></li></ol><h2 id="integrasi-fungsi-interaksi-pengguna-dengan-cesium-viewer" tabindex="-1"><strong>Integrasi Fungsi Interaksi Pengguna dengan Cesium Viewer</strong> <a class="header-anchor" href="#integrasi-fungsi-interaksi-pengguna-dengan-cesium-viewer" aria-label="Permalink to &quot;**Integrasi Fungsi Interaksi Pengguna dengan Cesium Viewer**&quot;">​</a></h2><ol><li><p>Tahap pertama buat fungsi memanggil dan mengaktifkan fungsi interaksi pengguna pada peta 3D, kemudian hubungkan <strong>kontrolInteraksi</strong> dengan panel kontrol layer 3D, sehingga fitur interaksi dapat digunakan bersamaan dengan layer yang ditampilkan.</p><p><img src="'+y+'" alt=""></p></li><li><p>Tahap kedua pastikan fungsi addInteraksiPengguna telah terpanggil pada halaman <strong>CesiumViewer.jsx</strong>.</p><p><img src="'+j+'" alt=""></p></li><li><p>Berikut ini merupakan hasil tampilan interaksi pengguna ketika mengklik data 2d jaringan jalan.</p><p><img src="'+P+'" alt="image.png"></p></li><li><p>Hasil interaksi pengguna ketika mengklik data polygon batas administrasi.</p><p><img src="'+I+'" alt="image.png"></p></li><li><p>Hasil interaksi pengguna ketika mengklik pada bagian objek 3d bangunan.</p><p><img src="'+D+'" alt="image.png"></p></li></ol>',6)])])}const E=n(B,[["render",T]]);export{q as __pageData,E as default};
